package io.aetheris.orchestrator.remote;import jakarta.persistence.*;import java.time.Instant;import java.util.*;@Entity @Table(name="aetheris_remote_companion_sessions") public class RemoteCompanionSessionEntity {@Id private UUID id;@Column(nullable=false,length=64) private String tokenHash;@Column(nullable=false,length=2000) private String capabilitiesCsv;@Column(nullable=false) private Instant createdAt;@Column(nullable=false) private Instant expiresAt;@Column(nullable=false) private boolean revoked;protected RemoteCompanionSessionEntity(){}public RemoteCompanionSessionEntity(UUID id,String tokenHash,Set<String> caps,Instant expiresAt){this.id=id;this.tokenHash=tokenHash;this.capabilitiesCsv=String.join(",",new TreeSet<>(caps));this.createdAt=Instant.now();this.expiresAt=expiresAt;}public UUID getId(){return id;}public String getTokenHash(){return tokenHash;}public Instant getCreatedAt(){return createdAt;}public Instant getExpiresAt(){return expiresAt;}public boolean isRevoked(){return revoked;}public Set<String> capabilities(){return capabilitiesCsv.isBlank()?Set.of():new LinkedHashSet<>(Arrays.asList(capabilitiesCsv.split(",")));}public void revoke(){revoked=true;}}
